package com.mycompany.rentalmanagement.dao;
import com.mycompany.rentalmanagement.DBConnection;import com.mycompany.rentalmanagement.util.PasswordUtil;import java.sql.*;import java.util.*;
public class UserDAO {public Map<String,String> authenticate(String username,String password)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT username,password_hash,full_name,role FROM users WHERE username=? AND active=1")){p.setString(1,username);try(ResultSet r=p.executeQuery()){if(r.next()&&PasswordUtil.verify(password,r.getString("password_hash"))){Map<String,String> m=new HashMap<>();m.put("username",r.getString("username"));m.put("fullName",r.getString("full_name"));m.put("role",r.getString("role"));return m;}return null;}}}}
